<template><Card class="s3-manager"><header class="header"><div><h2>核销记录</h2><p>查询成功事实与拒绝审计；凭证查询不计为成功核销。</p></div></header><Form inline class="query" @submit.native.prevent="search"><FormItem label="店铺 / 订单"><Input v-model="q" clearable maxlength="64" placeholder="店名或订单号" @on-enter="search"/></FormItem><FormItem label="点位名称"><Input v-model="pointName" clearable maxlength="50" placeholder="输入点位名称"/></FormItem><FormItem label="操作人"><Input v-model="operatorName" clearable maxlength="50" placeholder="输入操作人名称"/></FormItem><FormItem label="结果"><Select v-model="result" clearable><Option value="SUCCESS">成功核销</Option><Option value="REJECTED">拒绝审计</Option></Select></FormItem><FormItem label="发生日期（北京）"><DatePicker v-model="dates" type="daterange" placeholder="选择日期范围" style="width:240px"/></FormItem><Button type="primary" :loading="loading" @click="search">查询</Button><Button @click="reset">重置</Button></Form><Alert v-if="error" type="error" show-icon>{{error}} <Button type="text" @click="load">重新读取</Button></Alert><div v-if="!error" class="table-scroll"><Table :columns="columns" :data="records" :loading="loading" no-data-text="当前条件下没有记录"><template slot="point" slot-scope="{row}">{{row.point&&row.point.name||row.pointName||'点位不可见'}}<p class="meta">{{row.point&&row.point.address||''}}</p></template><template slot="operator" slot-scope="{row}">{{row.operatorName||'名称未提供'}}<p class="meta">{{row.operatorId}}</p></template><template slot="result" slot-scope="{row}"><Tag :color="row.result==='SUCCESS'?'green':'orange'">{{label(row.result)}}</Tag></template><template slot="time" slot-scope="{row}">{{date(row.at)}}</template><template slot="operation" slot-scope="{row}"><Button size="small" @click="open(row.id)">查看记录</Button></template></Table></div><Page v-if="!error" :total="total" :current="page" :page-size="20" show-total @on-change="turn"/></Card></template>
<script>
import {stage3Read} from '@/api/stage3';import {managerSession} from '@/libs/manager-session';import {date,label,day,range,restoreDates} from './presentation.cjs';
export default{data(){const q=this.$route.query;return {q:q.q||'',pointName:q.pointName||'',operatorName:q.operatorName||'',result:q.result||'',dates:restoreDates(q),page:Number(q.page)||1,records:[],total:0,error:'',loading:false,ticket:0,columns:[{title:'店铺',key:'storeName',minWidth:160},{title:'来源订单',key:'orderSn',minWidth:220},{title:'核销点位',slot:'point',minWidth:220},{title:'操作人',slot:'operator',minWidth:170},{title:'结果',slot:'result',minWidth:120},{title:'发生时间',slot:'time',minWidth:190},{title:'操作',slot:'operation',width:110}]}},mounted(){this.load()},beforeDestroy(){this.ticket++},methods:{date,label,query(){const query={pageNumber:this.page,pageSize:20};for(const key of ['q','pointName','operatorName','result'])if(this[key])query[key]=this[key];Object.assign(query,range(this.dates));return query},async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const v=await stage3Read('/verifications',this.query());if(ticket===this.ticket&&managerSession.sameSession(owner)){this.records=v.records;this.total=v.total}}catch(e){if(ticket===this.ticket){this.records=[];this.total=0;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},remember(){const query={page:String(this.page)};for(const key of ['q','pointName','operatorName','result'])if(this[key])query[key]=this[key];if(this.dates[0])query.fromDay=day(this.dates[0]);if(this.dates[1])query.toDay=day(this.dates[1]);this.$router.replace({path:'/s3/verifications',query}).catch(()=>{})},search(){this.page=1;this.remember();this.load()},reset(){this.q='';this.pointName='';this.operatorName='';this.result='';this.dates=[];this.search()},turn(page){this.page=page;this.remember();this.load()},open(id){this.$router.push({path:'/s3/verifications/'+id,query:this.$route.query})}}};
</script><style lang="scss">@import './stage3.scss';</style>
